PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT ?earlierFilm ?earlierDirector ?earlierDirectorLabel ?earlierDeath ?laterFilm ?laterDirector ?laterDirectorLabel ?laterDeath WHERE {
  VALUES ?f1 {
    dbr:John_Jaffer_Janardhanan dbr:Kamakalawa
  }
  VALUES ?f2 {
    dbr:John_Jaffer_Janardhanan dbr:Kamakalawa
  }
  FILTER(?f1 != ?f2)
  ?f1 dbo:director ?d1 .
  ?f2 dbo:director ?d2 .
  OPTIONAL {
    ?d1 dbo:deathDate ?death1
  }
  OPTIONAL {
    ?d1 dbp:death_date ?death1b
  }
  BIND(COALESCE(?death1 , ?death1b) AS ?death1f)
  OPTIONAL {
    ?d2 dbo:deathDate ?death2
  }
  OPTIONAL {
    ?d2 dbp:death_date ?death2b
  }
  BIND(COALESCE(?death2 , ?death2b) AS ?death2f)
  FILTER(bound(?death1f) && bound(?death2f) && ?death1f < ?death2f)
  BIND(?f1 AS ?earlierFilm)
  BIND(?d1 AS ?earlierDirector)
  BIND(?death1f AS ?earlierDeath)
  BIND(?f2 AS ?laterFilm)
  BIND(?d2 AS ?laterDirector)
  BIND(?death2f AS ?laterDeath)
  OPTIONAL {
    ?d1 rdfs:label ?earlierDirectorLabel
    FILTER(lang(?earlierDirectorLabel) = 'en')
  }
  OPTIONAL {
    ?d2 rdfs:label ?laterDirectorLabel
    FILTER(lang(?laterDirectorLabel) = 'en')
  }
}

