PREFIX dbp: <http://dbpedia.org/property/>
SELECT ?album ?albumLabel ?date WHERE {
  VALUES ?album {
    dbr:Sol_Niger_Within dbr:The_Magic_Place
  }
  OPTIONAL {
    ?album dbp:released ?dbp_released
  }
  OPTIONAL {
    ?album dbo:releaseDate ?dbo_releaseDate
  }
  OPTIONAL {
    ?album rdfs:label ?albumLabel .
    FILTER(lang(?albumLabel) = 'en')
  }
  BIND(IF(BOUND(?dbp_released) , IF(datatype(?dbp_released) = xsd:date , ?dbp_released , IF(datatype(?dbp_released) = xsd:integer , xsd:date(CONCAT(STR(?dbp_released) , "-01-01")) , ?dbp_released)) , ?dbo_releaseDate) AS ?date)
}
